local rows={}
for _,group in ipairs(groups)do
  for _,cell in ipairs(group.cells)do
    local row={id=cell[1],quadrant=cell[2],sourceCells=cell[3],sourceFiles=files[group.files]}
    for key,value in pairs(group)do
      if key~='files' and key~='art' and key~='cells' then row[key]=value end
    end
    for key,value in pairs(art[group.art])do row[key]=value end
    rows[#rows+1]=row
  end
end
return rows

end)()
local function key(r)return r.game..":"..r.map..":"..r.id..":"..r.quadrant end
local lookup={}
for _,r in ipairs(fixes)do assert(not lookup[key(r)],"Duplicate Goldenrod source supersession key");lookup[key(r)]=r end
local n=0
for i,r in ipairs(rows)do if r.map and lookup[key(r)]then rows[i]=lookup[key(r)];n=n+1 end end
assert(n==216,"Goldenrod native interior source scope changed")
end
-- END NATIVE CRYSTALDUST GOLDENROD INTERIOR DETAILS
return rows
